    }
    return result;
}

private void backtrack(int[] nums, boolean[] visited, List<Integer> current, List<List<Integer>> result) {
    if (current.size() == nums.length) {
        result.add(new ArrayList<>(current));
        return;
    }
    for (int i = 0; i < nums.length; i++) {
        if (visited[i]) continue;
        visited[i] = true;
        current.add(nums[i]);
        backtrack(nums, visited, current, result);
        current.remove(current.size() - 1);
        visited[i] = false;
    }
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    // Build a set of substrings for each string
    List<Set<String>> substringSets = new ArrayList<>(strings.size());
    int minLen = Integer.MAX_VALUE;
    for (String s : strings) {
        if (s == null) {
            substringSets.add(Collections.emptySet());
            continue;
        }
        minLen = Math.min(minLen, s.length());
        Set<String> set = new HashSet<>();
        int len = s.length();
        for (int i = 0; i < len; i++) {
            for (int j = i + 1; j <= len; j++) {
                set.add(s.substring(i, j));
            }
        }
        substringSets.add(set);
    }
    if (minLen == Integer.MAX_VALUE) { // all were null
        return 0;
    }
    // Use the first string as source of candidate substrings
    String first = strings.get(0);
    if (first == null) {
        return 0;
    }
    for (int l = minLen; l >= 1; l--) {
        Set<String> seen = new HashSet<>();
        for (int i = 0; i <= first.length() - l; i++) {
            String candidate = first.substring(i, i + l);
            if (!seen.add(candidate)) {
                continue; // already processed this substring
            }
            String rev = new StringBuilder(candidate).reverse().toString();
            boolean ok = true;
            for (Set<String> set : substringSets) {
                if (!set.contains(candidate) && !set.contains(rev)) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                return l;
            }
        }
    }
    return 0;
}

