                java.util.Deque<int[]> stack = new java.util.ArrayDeque<>();
                stack.push(new int[] {r, c});
                visited[r][c] = true;

                while (!stack.isEmpty()) {
                    int[] pos = stack.pop();
                    int curR = pos[0];
                    int curC = pos[1];

                    // Explore all 8 neighboring cells
                    for (int dir = 0; dir < 8; dir++) {
                        int newR = curR + dRow[dir];
                        int newC = curC + dCol[dir];

                        if (newR >= 0 && newR < rows &&
                            newC >= 0 && newC < cols &&
