                continue;
            }
            String node1 = x1 + "," + y1;
            String node2 = x2 + "," + y2;
            adj.computeIfAbsent(node1, k -> new java.util.ArrayList<>()).add(node2);
            adj.computeIfAbsent(node2, k -> new java.util.ArrayList<>()).add(node1);
        }
    }
    String startKey = start[0] + "," + start[1];
    String endKey = end[0] + "," + end[1];
    java.util.Set<String> visited = new java.util.HashSet<>();
    java.util.ArrayDeque<String> queue = new java.util.ArrayDeque<>();
