    }

    int n = arr.length;
    // The array must contain an even number of elements to form pairs
    if (n % 2 != 0) {
        return false;
    }

    // Count occurrences of each remainder modulo k
    int[] count = new int[k];
    for (int num : arr) {
        int rem = num % k;
        if (rem < 0) {
            rem += k; // Ensure non-negative remainder
        }
