    }

    // Remainder 0 must have an even count
    if (count[0] % 2 != 0) {
        return false;
    }

    // For each remainder r (1 <= r <= k/2), check its complement (k - r)
    int limit = k / 2;
    for (int r = 1; r <= limit; r++) {
        int complement = k - r;
        if (r == complement) { // This occurs when k is even and r == k/2
            if (count[r] % 2 != 0) {
                return false;
            }
        } else {
            if (count[r] != count[complement]) {
