    if (arr.length % 2 != 0) return false;                     // Must have even number of elements to form pairs

    int[] remainderCount = new int[k];
    for (int num : arr) {
        int r = ((num % k) + k) % k;                          // Handles negative numbers correctly
        remainderCount[r]++;
    }

    // Remainder 0 elements must pair among themselves
    if (remainderCount[0] % 2 != 0) return false;

    // If k is even, the remainder k/2 also must pair among themselves
    if (k % 2 == 0) {
        if (remainderCount[k / 2] % 2 != 0) return false;
    }

    // For all other remainders, counts must match with complementary remainder
    for (int r = 1; r <= k / 2; r++) {
        if (r == k - r) continue;               // Skip the middle remainder already handled
        if (remainderCount[r] != remainderCount[k - r]) return false;
    }

    return true;
}

