    dfs(0, -1, adj, hasApple, time);
    return time[0];
}

private boolean dfs(int node, int parent, List<Integer>[] adj, boolean[] hasApple, int[] time) {
    boolean containsApple = hasApple[node];
    for (int child : adj[node]) {
        if (child == parent) {
            continue;
        }
        if (dfs(child, node, adj, hasApple, time)) {
            time[0] += 2; // go to child and return
            containsApple = true;
        }
    }
    return containsApple;
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }
    int[] freq = new int[256]; // support ASCII characters
    for (char c : s.toCharArray()) {
        freq[c]++;
    }
    StringBuilder sb = new StringBuilder();
    int total = s.length();

    while (total > 0) {
        // Ascending pass: pick smallest remaining characters
        for (int i = 0; i < 256 && total > 0; i++) {
            if (freq[i] > 0) {
                sb.append((char) i);
                freq[i]--;
                total--;
            }
        }
        // Descending pass: pick largest remaining characters
        for (int i = 255; i >= 0 && total > 0; i--) {
            if (freq[i] > 0) {
                sb.append((char) i);
                freq[i]--;
                total--;
            }
        }
    }
    return sb.toString();
}

