            costToStep0 = costToStep1;
            costToStep1 = newCost;
        }
        // costToStep1 now holds the minimal cost to reach the top (step n).
        return costToStep1;
    } catch (Exception e) {
        // In case of unexpected errors, return 0 as a safe fallback.
        return 0;
    }
}

