public boolean hasAllCodes(String s, int k) {
    try {
        if (s == null || k < 0) {
            return false;
        }
        int n = s.length();
        if (k == 0) {
            return true;
        }
        if (n < k) {
            return false;
        }
        // Limit k to a reasonable size to avoid excessive memory usage
        if (k > 20) {
            return false;
        }
        int totalCodes = 1 << k;
        boolean[] seen = new boolean[totalCodes];
        int code = 0;
        // Build the first code of length k
        for (int i = 0; i < k; i++) {
            code = (code << 1) | (s.charAt(i) - '0');
        }
        seen[code] = true;
        int mask = totalCodes - 1;
        // Slide the window across the string
        for (int i = k; i < n; i++) {
            code = ((code << 1) & mask) | (s.charAt(i) - '0');
            seen[code] = true;
        }
        // Check if all codes have been seen
        for (boolean flag : seen) {
            if (!flag) {
                return false;
            }
        }
        return true;
    } catch (Exception e) {
        return false;
    }
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || k < 0) {
        throw new IllegalArgumentException("Input string cannot be null and k must be non-negative");
    }
    if (k == 0) {
        // Only the empty string needs to appear.
        return true;
    }
    int totalCodes = 1 << k;
    if (s.length() < totalCodes) {
        // Not enough substrings to cover all possible codes.
        return false;
    }

    boolean[] seen = new boolean[totalCodes];
    int mask = 0;
    int maskLimit = totalCodes - 1; // (1 << k) - 1

    for (int i = 0; i < s.length(); i++) {
        int bit = s.charAt(i) - '0';
        if (bit < 0 || bit > 1) {
            throw new IllegalArgumentException("Input string must be a binary string containing only '0' and '1'");
        }
        mask = ((mask << 1) & maskLimit) | bit;
        if (i >= k - 1) {
            seen[mask] = true;
        }
    }

    for (boolean present : seen) {
        if (!present) {
            return false;
        }
    }
    return true;
}

