            // Unexpected character: treat as a contributes to imbalance
            // Depending on requirements, you could throw an exception here.
            // For robustness, we ignore it.
        }
    }

    // Any remaining unmatched '(' need ')' to close them
    return insertions + balance;
}

public int minInsertions(String s) {
    if (s == null) {
        return 0;
    }
    int unmatchedLeft = 0; // number of unmatched '(' seen so far
    int insertions = 0;     // number of '(' to insert before a ')' without a match
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            unmatchedLeft++;
        } else if (c == ')') {
            if (unmatchedLeft > 0) {
                unmatchedLeft--;          // match with an existing '('
            } else {
                insertions++;              // need to insert a '(' before this ')'
            }
        } else {
            // input should consist of '(' and ')'; if not, ignore or handle as needed
            throw new IllegalArgumentException("Invalid character in input string: " + c);
        }
    }
    // remaining unmatched '(' require ')' insertions
    return insertions + unmatchedLeft;
}

