public int maxAbsoluteSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    try {
        // Maximum subarray sum (Kadane's algorithm)
        int maxSum = nums[0];
        int currentMax = nums[0];
        // Minimum subarray sum (Kadane's algorithm on negated values)
        int minSum = nums[0];
        int currentMin = nums[0];

        for (int i = 1; i < nums.length; i++) {
            int val = nums[i];
            currentMax = Math.max(val, currentMax + val);
            maxSum = Math.max(maxSum, currentMax);

            currentMin = Math.min(val, currentMin + val);
            minSum = Math.min(minSum, currentMin);
        }

        int maxAbsMax = Math.abs(maxSum);
        int maxAbsMin = Math.abs(minSum);
        return Math.max(maxAbsMax, maxAbsMin);
    } catch (Exception e) {
        // In case of unexpected runtime issues, return 0
        return 0;
    }
}

