public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }
    java.util.ArrayList<Integer> low = new java.util.ArrayList<>();
    java.util.ArrayList<Integer> high = new java.util.ArrayList<>();
    int limit = (int) Math.sqrt(n);
    for (int i = 1; i <= limit; i++) {
        if (n % i == 0) {
            low.add(i);
            int other = n / i;
            if (other != i) {
                high.add(other);
            }
        }
    }
    java.util.Collections.sort(high);
    int total = low.size() + high.size();
    if (k > total) {
        return -1;
    }
    if (k <= low.size()) {
        return low.get(k - 1);
    } else {
        return high.get(k - low.size() - 1);
    }
}

public int kthFactor(int n, int k) {
    // Validate inputs
    if (n <= 0 || k <= 0) {
        return -1;
    }

    int sqrtN = (int) Math.sqrt(n);
    java.util.List<Integer> small = new java.util.ArrayList<>();
    java.util.List<Integer> large = new java.util.ArrayList<>();

    for (int i = 1; i <= sqrtN; i++) {
        if (n % i == 0) {
            small.add(i);
            int div = n / i;
            if (div != i) {
                large.add(div);
            }
        }
    }

    int totalFactors = small.size() + large.size();
    if (k > totalFactors) {
        return -1;
    }

    if (k <= small.size()) {
        return small.get(k - 1);
    }

    int remaining = k - small.size();
    // large list stores larger factors in ascending order of i, which corresponds
    // to descending order of the factor values. Reverse it for ascending.
    int indexInLarge = large.size() - remaining;
    return large.get(indexInLarge);
}

