    return sb.toString();
}

public int maxUniqueSplit(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    java.util.HashSet<String> used = new java.util.HashSet<>();
    return backtrack(s, 0, used);
}

private int backtrack(String s, int index, java.util.HashSet<String> used) {
    int n = s.length();
    if (index == n) {
        return 0;
    }
    int maxSplits = 0;
    for (int end = index + 1; end <= n; end++) {
        String sub = s.substring(index, end);
        if (used.contains(sub)) {
            continue; // duplicate substring, cannot use
        }
        used.add(sub);
        int splits = 1 + backtrack(s, end, used);
        if (splits > maxSplits) {
            maxSplits = splits;
        }
        used.remove(sub);
    }
    return maxSplits;
}

public int maxUniqueSplit(String s) {
    try {
        if (s == null || s.isEmpty()) {
            return 0;
        }
        int n = s.length();
        int max = 0;
        int totalMasks = 1 << (n - 1);
        for (int mask = 0; mask < totalMasks; mask++) {
            java.util.Set<String> seen = new java.util.HashSet<>();
            int prev = 0;
            boolean valid = true;
            int count = 0;
            for (int i = 0; i < n - 1; i++) {
                if ((mask & (1 << i)) != 0) {
                    String sub = s.substring(prev, i + 1);
                    if (!seen.add(sub)) {
                        valid = false;
                        break;
                    }
                    count++;
                    prev = i + 1;
                }
            }
            if (!valid) {
                continue;
            }
            String last = s.substring(prev);
            if (!seen.add(last)) {
                continue;
            }
            count++;
            if (count > max) {
                max = count;
            }
        }
        return max;
    } catch (Exception e) {
        return 0;
    }
}

