    return best[0];
}

private void backtrack(String s, int index, java.util.Set<String> used, int[] best) {
    if (index == s.length()) {
        if (used.size() > best[0]) {
            best[0] = used.size();
        }
        return;
    }
    for (int end = index + 1; end <= s.length(); end++) {
        String sub = s.substring(index, end);
        if (!used.contains(sub)) {
            used.add(sub);
            backtrack(s, end, used, best);
            used.remove(sub);
        }
    }
}

