    }
    // Best count found so far
    int[] best = new int[1];
    // Backtracking helper
    backtrack(s, 0, new java.util.HashSet<>(), 0, best);
    return best[0];
}

private void backtrack(String s, int index, java.util.Set<String> seen, int count, int[] best) {
    if (index == s.length()) {
        if (count > best[0]) {
            best[0] = count;
        }
        return;
    }
    for (int end = index + 1; end <= s.length(); end++) {
        String sub = s.substring(index, end);
        if (!seen.contains(sub)) {
            seen.add(sub);
            backtrack(s, end, seen, count + 1, best);
            seen.remove(sub);
        }
    }
}

