    }

    char[] result = new char[n];
    int remaining = k;

    for (int i = n - 1; i >= 0; i--) {
        // The minimum sum required for the remaining i positions (1 each)
        int minForRest = i;
        // Choose the smallest value for the current position that still allows
        // the rest of the positions to reach the required sum.
        int value = Math.min(26, remaining - minForRest);
        if (value < 1) { // this should not happen due to the above bounds check
            value = 1;
        }
        result[i] = (char) ('a' + value - 1);
        remaining -= value;
    }

    return new String(result);
}

