    ArrayDeque<Long> queue = new ArrayDeque<>();
    // Initialize queue with single-digit numbers 1-9
    for (int i = 1; i <= 9; i++) {
        queue.offer((long) i);
    }
    while (!queue.isEmpty()) {
        long num = queue.poll();
        if (num > high) {
