        }
        if (lastDigit < 9) {
            long next = num * 10 + (lastDigit + 1);
            queue.offer(next);
        }
    }
    // The generated numbers are already in ascending order due to BFS order,
    // but sorting ensures correct order if needed.
    Collections.sort(result);
    return result;
}

