public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }

    char[][] pairs = {
        {'0', '0'},
        {'1', '1'},
        {'6', '9'},
        {'8', '8'},
        {'9', '6'}
    };

    char[] current = new char[n];
    build(0, n - 1, current, pairs, result, n);
    return result;
}

private static void build(int left, int right, char[] current, char[][] pairs,
                          List<String> result, int totalLength) {
    if (left > right) {
        result.add(new String(current));
        return;
    }

    // Middle position for odd length
    if (left == right) {
        for (char[] p : pairs) {
            if (p[0] == p[1]) { // center can only be 0,1,8
                current[left] = p[0];
                result.add(new String(current));
            }
        }
        return;
    }

    for (char[] p : pairs) {
        // Leading zero not allowed when length > 1
        if (left == 0 && totalLength > 1 && p[0] == '0') {
            continue;
        }
        current[left] = p[0];
        current[right] = p[1];
        build(left + 1, right - 1, current, pairs, result, totalLength);
    }
}

public static List<String> centerSymmetricNumbers(int n) {
    if (n <= 0) {
        return new ArrayList<>();
    }
    return generate(n, n);
}

public static boolean isBoomerang(int[][] points) {
    try {
        if (points == null || points.length != 3) {
            return false;
        }
        // Ensure each point has exactly two coordinates
        for (int i = 0; i < 3; i++) {
            if (points[i] == null || points[i].length != 2) {
                return false;
            }
        }
        // Check for duplicate points
        for (int i = 0; i < 3; i++) {
            for (int j = i + 1; j < 3; j++) {
                if (points[i][0] == points[j][0] && points[i][1] == points[j][1]) {
                    return false;
                }
            }
        }
        // Calculate area of triangle formed by the three points
        int x1 = points[0][0], y1 = points[0][1];
        int x2 = points[1][0], y2 = points[1][1];
        int x3 = points[2][0], y3 = points[2][1];
        int area2 = (x1 - x2) * (y3 - y2) - (y1 - y2) * (x3 - x2);
        // If area is zero, points are collinear
        return area2 != 0;
    } catch (Exception e) {
        // Any unexpected error results in false
        return false;
    }
}

