public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer.");
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        dp[i] = Integer.MAX_VALUE;
    }

    java.util.ArrayList<Integer> squares = new java.util.ArrayList<>();
    for (int i = 1; i * i <= n; i++) {
        squares.add(i * i);
    }

    for (int i = 1; i <= n; i++) {
        for (int sq : squares) {
            if (sq > i) {
                break;
            }
            int candidate = dp[i - sq] + 1;
            if (candidate < dp[i]) {
                dp[i] = candidate;
            }
        }
    }
    return dp[n];
}

